import json
from pathlib import Path

base = Path('.')
inventory = {k: int(v) for k, v in json.loads((base / 'inventory.json').read_text()).items()}
rejected = []

lines = (base / 'transactions.txt').read_text().splitlines()
for i, line in enumerate(lines, start=1):
    line = line.strip()
    if not line:
        continue
    parts = line.split()
    op, sku, qty_s = parts[0], parts[1], parts[2]
    qty = int(qty_s)
    if op == 'add':
        inventory[sku] = inventory.get(sku, 0) + qty
    elif op == 'remove':
        if sku not in inventory or inventory[sku] - qty < 0:
            rejected.append(i)
        else:
            inventory[sku] -= qty
    else:
        raise ValueError(f'unknown op {op!r} on line {i}: {line!r}')

(base / 'inventory_after.json').write_text(json.dumps(inventory, indent=2) + '\n')
(base / 'rejected.txt').write_text(''.join(f'{n}\n' for n in rejected))
print(json.dumps(inventory, indent=2))
print('rejected:', rejected)
